{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>Investment — {{BUSINESS_NAME}}</title>
<style>
:root{--bg:#f7fbf9;--card:#ffffff;--accent:#2f8f7a;--muted:#6b7276;--glass:rgba(255,255,255,0.7)}
*{box-sizing:border-box}
html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,var(--bg),#eef7f3);color:#123;}
.header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:transparent}
.brand{display:flex;align-items:center;gap:14px}
.logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#57b693);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
.nav{display:flex;gap:14px}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a:hover{background:var(--glass);color:#0b3b31}
.container{max-width:1100px;margin:30px auto;padding:24px}
.hero{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:center}
.hero .lead{padding:22px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);box-shadow:0 6px 20px rgba(18,43,34,0.06)}
.kicker{color:var(--accent);font-weight:700;margin-bottom:8px}
.h1{font-size:28px;margin:0 0 10px}
.h1 small{display:block;color:var(--muted);font-weight:600}
.p{color:var(--muted);margin:0 0 16px}
.cta{display:inline-flex;gap:8px;align-items:center;background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none}
.side-card{padding:18px;border-radius:12px;background:linear-gradient(180deg,#ffffff,#f6fcf9);box-shadow:0 6px 18px rgba(47,143,122,0.08)}
.toggle{display:flex;align-items:center;gap:10px;font-weight:700}
.switch{background:#eef6f3;border-radius:999px;padding:6px;display:inline-flex;align-items:center}
.switch button{appearance:none;border:0;background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer}
.switch button.active{background:var(--accent);color:#fff}
.prices{display:flex;flex-direction:column;gap:12px;margin-top:12px}
.card{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-radius:10px;background:var(--card);box-shadow:0 4px 12px rgba(18,43,34,0.04)}
.card .meta{display:flex;flex-direction:column}
.card .name{font-weight:800}
.card .desc{color:var(--muted);font-size:13px}
.price{font-weight:900;font-size:20px;color:var(--accent)}
.badge{background:#eef7f4;color:var(--accent);padding:6px 8px;border-radius:8px;font-weight:700;font-size:12px}
.note{font-size:12px;color:var(--muted);margin-top:10px}
.footer-cta{margin-top:18px;display:flex;gap:10px}
.secondary{background:transparent;border:1px solid #e4efe9;padding:10px 12px;border-radius:10px;color:var(--accent)}
.small{font-size:13px;color:var(--muted)}
.pattern{position:absolute;inset:0;pointer-events:none;opacity:0.14}
@media (max-width:880px){.hero{grid-template-columns:1fr;}.side-card{order:-1}}
</style>
</head>
<body>
<div class='pattern' aria-hidden>
<!-- Inline unique SVG pattern -->
<svg width='100%' height='100%' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'>
<defs>
<linearGradient id='g1' x1='0' x2='1'><stop offset='0' stop-color='%232f8f7a' stop-opacity='0.06'/><stop offset='1' stop-color='%2357b693' stop-opacity='0.02'/></linearGradient>
</defs>
<rect width='100%' height='100%' fill='none'/>
<g transform='translate(-50,-20)'>
<circle cx='140' cy='90' r='120' fill='url(%23g1)' />
<path d='M210 400 C 170 260 480 260 430 420' fill='none' stroke='%232f8f7a' stroke-opacity='0.03' stroke-width='90' stroke-linecap='round'/>
<g transform='translate(600,120) rotate(30)'>
<rect x='0' y='0' width='260' height='160' rx='20' fill='%23ffffff' fill-opacity='0.04' />
</g>
</g>
</svg>
</div>
<header class='header container'>
<div class='brand'>
<div class='logo'>W</div>
<div>
<div style='font-weight:800'>{{BUSINESS_NAME}}</div>
<div class='small'>Balanced practice, steady progress</div>
</div>
</div>
<nav class='nav' aria-label='Primary'>
<a href='index.html'>Home</a>
<a href='about.html'>Philosophy</a>
<a href='programs.html'>Pathways</a>
<a href='services.html'>Offerings</a>
<a href='pricing.html'>Investment</a>
<a href='testimonials.html'>Proof</a>
<a href='book.html'>Schedule</a>
<a href='contact.html'>Connect</a>
</nav>
</header>
<main class='container'>
<section class='hero'>
<div class='lead'>
<div class='kicker'>Memberships — ongoing support</div>
<h1 class='h1'>Pricing framed around steady change <small>Membership options to fit a consistent practice</small></h1>
<p class='p'>Choose a structure that encourages habit formation, with clear checkpoints and guided practice. Memberships are built to support outcomes, rituals, and frameworks — not one-off fixes.</p>
<div class='footer-cta'>
<a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
<a class='secondary' href='book.html'>Book a planning call</a>
</div>
</div>
<aside class='side-card'>
<div style='display:flex;justify-content:space-between;align-items:center'>
<div class='toggle'>
<span class='small'>Charge</span>
<div class='switch' role='tablist' aria-label='Billing toggle'>
<button id='toggle-monthly' class='active' role='tab' aria-selected='true'>Monthly</button>
<button id='toggle-package' role='tab' aria-selected='false'>3-Month Pack</button>
</div>
</div>
<span class='badge'>Members only</span>
</div>
<div class='prices' id='pricing-list'>
<div class='card' data-month='79' data-package='210'>
<div class='meta'><div class='name'>Foundation</div><div class='desc'>Weekly check-ins + core habit map</div></div>
<div style='text-align:right'><div class='price' data-role='price'>${79}</div><div class='small'>per month</div></div>
</div>
<div class='card' data-month='149' data-package='400'>
<div class='meta'><div class='name'>Momentum</div><div class='desc'>Two coaching sessions + habit framework</div></div>
<div style='text-align:right'><div class='price' data-role='price'>${149}</div><div class='small'>per month</div></div>
</div>
<div class='card' data-month='269' data-package='720'>
<div class='meta'><div class='name'>Steady Practice</div><div class='desc'>Full support, unlimited messages, quarterly review</div></div>
<div style='text-align:right'><div class='price' data-role='price'>${269}</div><div class='small'>per month</div></div>
</div>
</div>
<div class='note'>Package prices billed upfront for three months. Toggle to see comparative monthly or pack pricing. Numbers animate for clarity.</div>
</aside>
</section>
<section style='margin-top:26px;background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(18,43,34,0.04)'>
<h3 style='margin:0 0 8px'>What you get</h3>
<ul style='margin:0;padding-left:18px;color:var(--muted)'>
<li>Simple practice plans tied to measurable behaviors</li>
<li>Weekly actions, habit checkpoints, and reflection prompts</li>
<li>Direct coaching time plus structured check-ins</li>
</ul>
<div style='margin-top:14px;display:flex;gap:10px;align-items:center'>
<a class='cta' href='{{PRIMARY_CTA_URL}}'>Start membership</a>
<a class='secondary' href='contact.html'>Ask a question</a>
</div>
</section>
</main>
<script>
// Pricing comparator with animated numbers
(function(){
const monthlyBtn = document.getElementById('toggle-monthly');
const packageBtn = document.getElementById('toggle-package');
const cards = document.querySelectorAll('.card');
let mode = 'monthly';
function animateValue(el, start, end, duration){
 const startTime = performance.now();
 function step(now){
   const progress = Math.min((now - startTime)/duration,1);
   const value = Math.round(start + (end - start) * (1 - Math.pow(1 - progress,2)) );
   el.textContent = '$' + value;
   if(progress < 1) requestAnimationFrame(step);
 }
 requestAnimationFrame(step);
}
function setMode(m){
 mode = m;
 monthlyBtn.classList.toggle('active', m==='monthly');
 monthlyBtn.setAttribute('aria-selected', m==='monthly');
 packageBtn.classList.toggle('active', m==='package');
 packageBtn.setAttribute('aria-selected', m==='package');
 cards.forEach(card=>{
   const priceEl = card.querySelector('[data-role="price"]');
   const from = parseInt(priceEl.textContent.replace(/[^0-9]/g,''),10) || 0;
   const to = m==='monthly' ? parseInt(card.getAttribute('data-month'),10) : parseInt(card.getAttribute('data-package'),10);
   animateValue(priceEl, from, to, 600);
   // update descriptor
   const small = priceEl.nextElementSibling;
   if(m==='monthly') small.textContent = 'per month'; else small.textContent = 'one-time (3 months)';
 });
}
monthlyBtn.addEventListener('click',()=> setMode('monthly'));
packageBtn.addEventListener('click',()=> setMode('package'));
// initialize
setMode('monthly');
})();
</script>
</body>
</html>"} 
