*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,#f6fcf9,#ffffff);color:#0b2b25}
.container{max-width:980px;margin:28px auto;padding:20px}
.header{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.brand{display:flex;gap:12px;align-items:center}
.logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#3aa07f,#2f8f7a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
.nav a{color:var(--muted);text-decoration:none;margin-left:12px}
.hero{padding:18px;background:var(--card);border-radius:12px;box-shadow:0 8px 30px rgba(47,143,122,0.06)}
.gallery{display:grid;grid-template-columns:1fr 260px;gap:18px;margin-top:16px}
.testimonial{padding:18px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#f6fdf8);min-height:160px;display:flex;flex-direction:column;justify-content:space-between}
.quote{font-style:italic;color:#0b2e27}
.author{margin-top:12px;font-weight:800}
.controls{display:flex;gap:8px;align-items:center}
.btn{background:#eef7f4;border:0;padding:8px 10px;border-radius:8px;cursor:pointer}
.badges{display:flex;flex-direction:column;gap:10px;padding:14px;background:#fff;border-radius:10px;box-shadow:0 6px 18px rgba(18,43,34,0.04)}
.badge{display:flex;gap:10px;align-items:center;padding:8px;border-radius:8px;background:#fbfffd}
.badge svg{width:36px;height:36px}
.tooltip{position:relative}
.tooltip .tip{position:absolute;background:#123;color:#fff;padding:8px;border-radius:8px;font-size:13px;transform:translateX(10px);left:100%;top:50%;white-space:nowrap;display:none}
.tooltip:focus-within .tip,.tooltip:hover .tip{display:block}
.small{color:var(--muted);font-size:13px}
.carousel-dots{display:flex;gap:8px;margin-top:10px}
.dot{width:10px;height:10px;border-radius:999px;background:#e6efe9}
.dot.active{background:var(--accent)}
.pattern{height:80px;margin-top:12px;border-radius:12px;overflow:hidden}
@media (max-width:900px){.gallery{grid-template-columns:1fr}} 
</style>
</head>
<body>
<div class='container'>
<header class='header'>
<div class='brand'>
<div class='logo'>W</div>
<div>
<div style='font-weight:800'>{{BUSINESS_NAME}}</div>
<div class='small'>Evidence of steady practice</div>
</div>
</div>
<nav class='nav' aria-label='Primary'>
<a href='index.html'>Home</a>
<a href='about.html'>Philosophy</a>
<a href='programs.html'>Pathways</a>
<a href='services.html'>Offerings</a>
<a href='pricing.html'>Investment</a>
<a href='testimonials.html'>Proof</a>
