<a href='contact.html'>Connect</a>
</nav>
</header>
<main>
<section class='hero'>
<h2 style='margin:0'>Client stories — progress as practice</h2>
<p class='small' style='margin:8px 0 0'>Real notes from clients who built routines and tracked small wins.</p>
<div class='gallery'>
<div>
<div class='testimonial' id='testimonial'>
<div>
<div class='quote' id='quote'>"I finally found a structure I could keep to. The clear checkpoints made habits feel doable."</div>
</div>
<div style='display:flex;justify-content:space-between;align-items:center'>
<div>
<div class='author' id='author'>— Alex, local teacher</div>
<div class='small' id='when'>6 months in</div>
</div>
<div class='controls'>
<button class='btn' id='prev' aria-label='Previous'>◀</button>
<button class='btn' id='next' aria-label='Next'>▶</button>
</div>
</div>
<div class='carousel-dots' id='dots' aria-hidden></div>
</div>
</div>
<aside class='badges'>
<div style='font-weight:800'>Credibility & press</div>
<div class='badge tooltip' tabindex='0'>
<svg viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'><circle cx='12' cy='12' r='10' stroke='%232f8f7a' stroke-width='1.5' fill='%23eaf8f2'/><path d='M8 12c1.333-2 3-3 4-3s2.667 1 4 3' stroke='%232f8f7a' stroke-width='1.2' stroke-linecap='round' stroke-linejoin='round'/></svg>
<div>
<div style='font-weight:700'>Wellness Digest</div>
<div class='small'>Featured series: sustainable practice</div>
</div>
<div class='tip'>Featured in an industry column about practice structures</div>
</div>
<div class='badge tooltip' tabindex='0'>
<svg viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'><rect x='3' y='4' width='18' height='16' rx='3' stroke='%230b3b31' stroke-width='1.2' fill='%23effaf5'/><path d='M7 13h10M7 9h6' stroke='%230b3b31' stroke-width='1.2' stroke-linecap='round'/></svg>
<div>
<div style='font-weight:700'>Local Health Journal</div>
<div class='small'>Community wellness column</div>
</div>
<div class='tip'>Interviewed about habit-based coaching approach</div>
</div>
<div class='badge tooltip' tabindex='0'>
<svg viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'><path d='M12 3l2.5 6H21l-5 3.8L17.5 21 12 16.6 6.5 21 8 13.8 3 10h6.5L12 3z' stroke='%232f8f7a' stroke-width='1.1' fill='%23e2fbef'/></svg>
<div>
<div style='font-weight:700'>Community Award</div>
<div class='small'>Recognized for behavior-change design</div>
</div>
<div class='tip'>Awarded for program design emphasizing simple rituals</div>
</div>
</aside>
</div>
<div class='pattern'>
<!-- Unique decorative SVG -->
<svg width='100%' height='80' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'>
<rect width='100%' height='80' fill='none'/>
<g fill='%232f8f7a' opacity='0.06'>
<circle cx='60' cy='40' r='40'/>
<circle cx='300' cy='10' r='48'/>
<path d='M520 80c-40-40-70-80-140-60' stroke='%232f8f7a' stroke-width='2' stroke-opacity='0.06' fill='none'/>
</g>
</svg>
</div>
</section>
</main>
<script>
// Proof gallery rotator + badges tooltips accessible
(function(){
const testimonials = [
 {quote:'"I finally found a structure I could keep to. The clear checkpoints made habits feel doable."', author:'Alex, teacher', when:'6 months in'},
 {quote:'"Small weekly intentions added up. My focus improved and I have routines I can repeat."', author:'Priya, designer', when:'3 months in'},
 {quote:'"Coaching helped me turn vague hopes into measurable actions. The habit map was a game-changer."', author:'Sam, entrepreneur', when:'5 months in'},
 {quote:'"I appreciate the frameworks — they made choices less stressful and progress more visible."', author:'Jordan, nurse', when:'4 months in'}
];
let idx = 0;
const quoteEl = document.getElementById('quote');
const authorEl = document.getElementById('author');
const whenEl = document.getElementById('when');
const prev = document.getElementById('prev');
const next = document.getElementById('next');
const dots = document.getElementById('dots');
function renderDots(){
 dots.innerHTML = '';
 testimonials.forEach((t,i)=>{
   const d = document.createElement('div'); d.className='dot'+(i===idx?' active':''); d.setAttribute('data-i',i);
   d.addEventListener('click',()=>{go(i)});
   dots.appendChild(d);
 });
}
function show(i){
 const t = testimonials[i];
 quoteEl.textContent = t.quote; authorEl.textContent = '— '+t.author; whenEl.textContent = t.when;
 Array.from(dots.children).forEach((d,di)=>d.classList.toggle('active', di===i));
}
function go(i){ idx = (i+testimonials.length)%testimonials.length; show(idx); }
prev.addEventListener('click',()=>go(idx-1));
next.addEventListener('click',()=>go(idx+1));
renderDots(); show(0);
let timer = setInterval(()=>go(idx+1),5000);
// pause on hover/focus
const gallery = document.querySelector('.gallery');
['mouseenter','focusin'].forEach(e=>gallery.addEventListener(e,()=>clearInterval(timer)));
['mouseleave','focusout'].forEach(e=>gallery.addEventListener(e,()=>{timer = setInterval(()=>go(idx+1),5000);}));
})();
</script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>Schedule — {{BUSINESS_NAME}}</title>
<style>
:root{--bg:#fbfffd;--accent:#2f8f7a;--muted:#64706a}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,var(--bg),#f4fbf9);color:#0b2b25}
.container{max-width:920px;margin:28px auto;padding:20px}
.header{display:flex;align-items:center;justify-content:space-between}
.logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#57b693,#2f8f7a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
.content{margin-top:18px;display:grid;grid-template-columns:1fr 360px;gap:18px}
.panel{background:#fff;padding:16px;border-radius:12px;box-shadow:0 8px 30px rgba(18,43,34,0.04)}
.form-row{display:flex;gap:10px;margin-bottom:10px}
.input,textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid #e9f3ef}
.button{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
.availability{display:flex;flex-direction:column;gap:8px}
.slot{padding:10px;border-radius:8px;background:#f5fff9;border:1px dashed #e1f4ea;cursor:pointer}
.slot.selected{background:linear-gradient(90deg,#ecfff7,#e6faf1);border-style:solid}
.note{font-size:13px;color:var(--muted)}
@media (max-width:900px){.content{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class='container'>
<header class='header'>
<div style='display:flex;gap:12px;align-items:center'>
<div class='logo'>W</div>
<div>
<div style='font-weight:800'>{{BUSINESS_NAME}}</div>
<div class='note'>Schedule an intake to design your practice.</div>
</div>
</div>
<nav aria-label='Primary'>
<a href='index.html' style='margin-left:12px;color:var(--muted)'>Home</a>
<a href='about.html' style='margin-left:12px;color:var(--muted)'>Philosophy</a>
<a href='programs.html' style='margin-left:12px;color:var(--muted)'>Pathways</a>
<a href='services.html' style='margin-left:12px;color:var(--muted)'>Offerings</a>
<a href='pricing.html' style='margin-left:12px;color:var(--muted)'>Investment</a>
<a href='testimonials.html' style='margin-left:12px;color:var(--muted)'>Proof</a>
<a href='book.html' style='margin-left:12px;color:var(--muted)'>Schedule</a>
<a href='contact.html' style='margin-left:12px;color:var(--muted)'>Connect</a>
</nav>
</header>
<main class='content'>
<section class='panel'>
<h3 style='margin:0 0 8px'>Plan a 30-minute intro</h3>
<p class='note'>A short planning call to clarify a starting point and outline the first month of practice. No medical advice — focus on habits, outcomes, and frameworks.</p>
<form id='booking-form' action='{{PRIMARY_CTA_URL}}' method='get' onsubmit='return submitForm(event)'>
<div class='form-row'><input class='input' name='name' placeholder='Your name' required></div>
<div class='form-row'><input class='input' name='email' placeholder='Email' type='email' required></div>
<div class='form-row'><input class='input' name='phone' placeholder='Phone (optional)'></div>
<div class='form-row'><select name='service' class='input'>
<option value='intro'>30-minute Planning Call</option>
<option value='foundation'>Foundation membership inquiry</option>
<option value='momentum'>Momentum membership inquiry</option>
</select></div>
<div style='margin-top:8px;display:flex;gap:8px;align-items:center'>
<button class='button' type='submit'>Schedule a time</button>
<a class='note' href='tel:{{PHONE}}' style='text-decoration:none;color:var(--muted)'>Or call {{PHONE}}</a>
</div>
</form>
<div style='margin-top:12px'>
<div style='font-weight:700;margin-bottom:6px'>What to expect</div>
<ul style='margin:0;padding-left:18px;color:var(--muted)'>
<li>15–30 minutes to map a starting practice</li>
<li>Clarity on one measurable habit to try for 2–4 weeks</li>
<li>A suggested next step you can opt into</li>
</ul>
</div>
</section>
<aside class='panel'>
<h4 style='margin:0 0 10px'>Available times</h4>
<div class='availability' id='availability'>
<div class='slot' data-time='2026-02-19T09:00'>Thu 9:00 AM</div>
<div class='slot' data-time='2026-02-19T11:00'>Thu 11:00 AM</div>
<div class='slot' data-time='2026-02-20T14:00'>Fri 2:00 PM</div>
<div class='slot' data-time='2026-02-22T10:00'>Sun 10:00 AM</div>
</div>
<div style='margin-top:12px' class='small note'>Select a slot to include it in the booking link. Times shown in {{CITY}}, {{STATE}} timezone.</div>
</aside>
</main>
<script>
// Simple booking helper: pick a slot and append to CTA URL as query
(function(){
const slots = document.querySelectorAll('.slot');
let selected = null;
slots.forEach(s=>{s.addEventListener('click',()=>{
